        for (int f2cu_i181 = 0; f2cu_i181 < (((nlev-1)-1)+1); ++f2cu_i181) prate[((1+f2cu_i181)-1)+((n-1))*(((nlev-1)+1))] = ftuv[((2+f2cu_i181)-1)+((n-1))*(((mod.nz-1)+1))]; // 1254
        for (int f2cu_i182 = 0; f2cu_i182 < ((mod.nz-1)+1); ++f2cu_i182) prate0[((1+f2cu_i182)-1)+((n-1))*(((mod.nz-1)+1))] = ftuv[((1+f2cu_i182)-1)+((n-1))*(((mod.nz-1)+1))]; // 1255
    } }
    // 1258: deallocate (fixed bounds)
    mod.ws_d = f2cu_wsd0; mod.ws_i = f2cu_wsi0;
}
#define TV_WS_D(nz) (1*(nz)*(nz) + 1149*(nz) + -213)
#define TV_WS_I(nz) (0*(nz)*(nz) + 2*(nz) + 0)
// END GENERATED

// Input fields, (TV_NIN, nz + 1, ny, nx) float32: level kte + 1 is read for
// z_at_w only; xlat/xlong are levels 0 of their rows.
#define TV_IN_T 0
#define TV_IN_P 1
#define TV_IN_RHO 2
#define TV_IN_P8W 3
#define TV_IN_T8W 4
#define TV_IN_ZW 5
#define TV_IN_QV 6
#define TV_IN_QC 7
#define TV_IN_O3 8
#define TV_IN_TAU 9    // tauaer1..4, then waer1..4 (13), gaer1..4 (17)
#define TV_IN_XLAT 21
#define TV_IN_XLONG 22
#define TV_NIN 23
// Output ph_* rows (photolysis_driver's names), (TV_NOUT, nz, ny, nx).
#define TV_NOUT 28

__device__ __forceinline__ float tv_in(const float *in, int f, int k, int j, int i,
                                       int nzp1, int ny, int nx) {
    return in[((f * nzp1 + k) * ny + j) * nx + i];
}

// photo_inti (module nz from kte and the 20 km exo top), on one thread.
// scal_d[0] = dobson; scal_i = {kcon, nintervals, nz, fatal}.
extern "C" __global__ void chem_ftuv_init(double *shared_d, int *shared_i, double *scal_d,
                                          int *scal_i, double *ws_d, int *ws_i,
                                          long long ws_d_len, long long ws_i_len,
                                          int kte, int nzm, int chem_opt) {
    if (blockIdx.x * blockDim.x + threadIdx.x != 0) return;
    FtuvModule mod;
    tv_bind_shared(mod, shared_d, shared_i, nzm);
    mod.dobson = 0.0; mod.kcon = 0; mod.nintervals = 0; mod.nz = nzm;
    mod.ws_d = ws_d; mod.ws_d_end = ws_d + ws_d_len;
    mod.ws_i = ws_i; mod.ws_i_end = ws_i + ws_i_len;
    mod.f2cu_fatal = 0;
    tv_photo_inti(mod, chem_opt, kte, 20.0);
    scal_d[0] = mod.dobson;
    scal_i[0] = mod.kcon; scal_i[1] = mod.nintervals; scal_i[2] = mod.nz;
    scal_i[3] = mod.f2cu_fatal;
}

// ftuv_driver for columns col0 .. col0 + ncols - 1 (i fastest), levels
// kts = 1 .. kte; ws_* hold ws_*_per words per thread.  gmt, julday and
// curr_secs as ftuv_driver receives them.  fatal[t]: a column's first
// fatal source line (negative: workspace overrun), or 0.
extern "C" __global__ void chem_ftuv(const double *shared_d, const int *shared_i,
                                     const double *scal_d, const int *scal_i,
                                     double *ws_d, int *ws_i,
                                     long long ws_d_per, long long ws_i_per,
                                     const float *in, float *out, int *fatal,
                                     int col0, int ncols, int nx, int ny, int kte, int nzm,
                                     int chem_opt, int aer_ra_feedback, int julday,
                                     float gmt, double curr_secs) {
    int t = blockIdx.x * blockDim.x + threadIdx.x;
    if (t >= ncols) return;
    int c = col0 + t;
    int i = c % nx, j = c / nx;
    int nzp1 = kte + 1;
    FtuvModule mod;
    tv_bind_shared(mod, (double *)shared_d, (int *)shared_i, nzm);
    mod.dobson = scal_d[0]; mod.kcon = scal_i[0]; mod.nintervals = scal_i[1]; mod.nz = scal_i[2];
    mod.f2cu_fatal = 0;
    double *wsd = ws_d + (long long)t * ws_d_per;
    int *wsi = ws_i + (long long)t * ws_i_per;
    mod.ws_d_end = wsd + ws_d_per;
    mod.ws_i_end = wsi + ws_i_per;
    // this column's sq, from the initial state
    double *sq = wsd;
    for (int q = 0; q < TV_SQ_SIZE(nzm); ++q) sq[q] = mod.sq[q];
    mod.sq = sq;
    wsd += TV_SQ_SIZE(nzm);
    // ftuv_driver's locals: temp .. asal (kts:kte+1), tauaer300 .. gaer999
    // (kts:kte; tauaer400/999 are declared kts:kte+1), prate(kts:kte+1,
    // tuv_jmax), radfld(nz, nw-1), adjcoe and prate0 (nz, tuv_jmax).
    double *temp = wsd; wsd += nzp1;
    double *o3 = wsd; wsd += nzp1;
    double *air = wsd; wsd += nzp1;
    double *zh = wsd; wsd += nzp1;
    double *rh = wsd; wsd += nzp1;
    double *xlwc = wsd; wsd += nzp1;
    double *aer = wsd; wsd += nzp1;      // acb1 .. asal: photoin never reads them
    double *tau = wsd; wsd += 12 * nzp1; // tauaer300,400,600,999, waer*, gaer*
    double *prate = wsd; wsd += nzp1 * TV_TUV_JMAX;
    double *radfld = wsd; wsd += nzm * (TV_NW - 1);
    double *adjcoe = wsd; wsd += nzm * TV_TUV_JMAX;
    double *prate0 = wsd; wsd += nzm * TV_TUV_JMAX;
    mod.ws_d = wsd;
    mod.ws_i = wsi;
    // xtime .. gmtp, module_ftuv_driver.F:338-342
    double xtime = DDIV(curr_secs, 60.0);
    double xhour = (double)((int)DADD((double)gmt, 0.01) + (int)DDIV(xtime, TV_M2S));
    double xmin = DADD(DMUL(TV_M2S, (double)gmt), DSUB(xtime, DMUL(xhour, TV_M2S)));
    double gmtp = fmod(xhour, 24.0);
    gmtp = DADD(gmtp, DDIV(xmin, TV_M2S));
    xlwc[0] = 0.0;  // xlwc(:) = 0._dp, :348
    for (int q = 0; q < nzp1; ++q) aer[q] = 0.0;
    for (int k = 1; k <= kte; ++k) {  // level_loop, :374-479
        int kp1 = k + 1;
        float tk = tv_in(in, TV_IN_T, k - 1, j, i, nzp1, ny, nx);
        float pk = tv_in(in, TV_IN_P, k - 1, j, i, nzp1, ny, nx);
        float rhok = tv_in(in, TV_IN_RHO, k - 1, j, i, nzp1, ny, nx);
        temp[kp1 - 1] = (double)tk;
        air[kp1 - 1] = DMUL(TV_XAIR_KG, (double)rhok);
        o3[kp1 - 1] = DMUL((double)tv_in(in, TV_IN_O3, k - 1, j, i, nzp1, ny, nx), 1.0e-6);
        double wrk = DSUB((double)tk, 273.0);
        double es = DMUL(6.11, glibc_pow(10.0, DDIV(DMUL(7.63, wrk), DADD(241.9, wrk))));
        double qs = DDIV(DMUL(0.622, es), DMUL((double)pk, 0.01));
        wrk = DDIV((double)tv_in(in, TV_IN_QV, k - 1, j, i, nzp1, ny, nx), qs);
        rh[kp1 - 1] = f2cu_maxd(0.0, f2cu_mind(1.0, wrk));
        // p_qc > 1 in both packages
        xlwc[kp1 - 1] = DMUL(DMUL(1.0e3, (double)tv_in(in, TV_IN_QC, k - 1, j, i, nzp1, ny, nx)),
                             (double)rhok);
        if (xlwc[kp1 - 1] < 1.0e-6) xlwc[kp1 - 1] = 0.0;
        float zw0 = tv_in(in, TV_IN_ZW, k - 1, j, i, nzp1, ny, nx);
        float zw1 = tv_in(in, TV_IN_ZW, kp1 - 1, j, i, nzp1, ny, nx);
        float zws = tv_in(in, TV_IN_ZW, 0, j, i, nzp1, ny, nx);
        zh[kp1 - 1] = DSUB(DMUL(DMUL(0.5, (double)FADD(zw1, zw0)), 0.001), DMUL((double)zws, 0.001));
        for (int n = 0; n < 12; ++n)
            tau[n * nzp1 + (k - 1)] = aer_ra_feedback == 1
                ? (double)tv_in(in, TV_IN_TAU + n, k - 1, j, i, nzp1, ny, nx) : 0.0;
    }
    float t8w = tv_in(in, TV_IN_T8W, 0, j, i, nzp1, ny, nx);
    float p8w = tv_in(in, TV_IN_P8W, 0, j, i, nzp1, ny, nx);
    temp[0] = (double)t8w;
    air[0] = DMUL(TV_XAIR_KG, (double)FDIV(FDIV(p8w, t8w), 287.0f));  // r_d
    o3[0] = o3[1];
    rh[0] = rh[1];
    xlwc[0] = 0.0;
    zh[0] = 0.0;
    for (int k = 2; k <= kte - 1; ++k)  // :501-503, in place, k ascending
        air[k - 1] = DADD(DMUL(0.5, air[k - 1]), DMUL(0.25, DADD(air[k - 2], air[k])));
    double alat = (double)tv_in(in, TV_IN_XLAT, 0, j, i, nzp1, ny, nx);
    double along = -(double)tv_in(in, TV_IN_XLONG, 0, j, i, nzp1, ny, nx);
    // (ftuv_driver's own calc_zenith only fills zen_angle, which it never reads)
    tv_photo(mod, chem_opt, kte + 1, TV_TUV_JMAX, julday, gmtp, alat, along,
             2.97450e+16, 3.60906e+21, mod.dobson, 1, zh, temp, air, rh, xlwc, o3,
             aer, aer, aer, aer, aer, aer, aer,
             tau, tau + nzp1, tau + 2 * nzp1, tau + 3 * nzp1,
             tau + 4 * nzp1, tau + 5 * nzp1, tau + 6 * nzp1, tau + 7 * nzp1,
             tau + 8 * nzp1, tau + 9 * nzp1, tau + 10 * nzp1, tau + 11 * nzp1,
             aer_ra_feedback, prate, radfld, adjcoe, prate0);
    // :530-580, ph_* = max(0, prate(k, pid) * m2s), rows in photolysis_driver's names
    const int pid[TV_NOUT] = {
        TV_PID_NO2, TV_PID_O31D, TV_PID_O33P, TV_PID_HONO, TV_PID_HNO3, TV_PID_HNO4,
        TV_PID_NO3O2, TV_PID_NO3O, TV_PID_H2O2, TV_PID_CH2OM, TV_PID_CH2OR, TV_PID_ALD,
        TV_PID_OP1, TV_PID_OP2, TV_PID_PAA, TV_PID_KET, TV_PID_GLYA, TV_PID_GLYB,
        TV_PID_MGLY, TV_PID_DCB, TV_PID_ONIT, TV_PID_MACR, 23, TV_PID_CL2, TV_PID_HOCL,
        TV_PID_FMCL, TV_PID_PAN, TV_PID_N2O5};
    for (int k = 1; k <= kte; ++k) {
        for (int n = 0; n < TV_NOUT; ++n) {
            double v = DMUL(prate[(pid[n] - 1) * nzp1 + (k - 1)], TV_M2S);
            if (n == 7) v = DMUL(v, TV_PH_NO3O_FACTOR);  // ph_no3o
            out[((n * kte + (k - 1)) * ny + j) * nx + i] = (float)f2cu_maxd(0.0, v);
        }
    }
    fatal[t] = mod.f2cu_fatal;
}
